input.sparql:
SELECT ?uri ?class WHERE {
  ?z a ?class .
  VALUES ?class { brick:Zone brick:PerimeterZone brick:Floor }
} LIMIT 50

SELECT (STR(?p) AS ?puri) (STR(?s) AS ?suri) ?class ?series WHERE {
  ?s ref:hasTimeseriesId ?series .
  ?s brick:hasLocation ?z .
  ?z rdfs:label "Perimeter_top_ZN_2" .
}

SELECT (STR(?s) AS ?suri) ?class ?series (STR(?loc) AS ?loc) (STR(?loc2) AS ?loc2) WHERE {
  ?s ref:hasTimeseriesId ?series .
  ?s a ?class .
} LIMIT 100

SELECT (STR(?p) AS ?puri) (STR(?class) AS ?class) (STR(?ref) AS ?ref) WHERE {
  ?p a ?class .
  ?p brick:hasLocation ?z .
  ?z a brick:Zone .
}

SELECT (STR(?p) AS ?puri) (STR(?z) AS ?zone) (STR(?ref) AS ?ref) WHERE {
  ?p a brick:Occupancy_Sensor .
  OPTIONAL { ?p brick:hasLocation ?z . }
  OPTIONAL { ?p ref:hasExternalReference ?ref . }
}
